mapper.update:
UPDATE shipment_records
SET resume_status = status, status = 'EXCEPTION', updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id} AND status = #{status}

UPDATE shipment_records
SET carrier = #{carrier}, tracking_number = #{trackingNumber}, updated_at = CURRENT_TIMESTAMP(6)
WHERE merchant_shipment_no = #{merchantShipmentNo}

mapper.select:
SELECT id
FROM shipment_records
WHERE status IN ('CREATED', 'PICKED_UP', 'IN_TRANSIT', 'AT_STATION', 'OUT_FOR_DELIVERY')
AND updated_at <= #{updatedBefore}
ORDER BY updated_at, id
LIMIT #{limit}

